CREATE TABLE IF NOT EXISTS d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

-- A baseline reproduces a schema; it cannot merge into one. Applying it over a
-- database that already has tables would leave a mixture of two schemas with no
-- migration history explaining either, and applying it over a partially
-- migrated database would claim every subsumed migration had run when some had
-- not. Both are unrecoverable without dropping the database, so this refuses
-- first, by name, before creating anything.
--
-- A D1 file is a flat sequence of statements with no branching, so the check is
-- a CHECK: the INSERT computes 1 only for an empty database and the constraint
-- rejects anything else. Migration 0090 guards itself the same way.
DROP TABLE IF EXISTS _baseline_empty_database_guard;
CREATE TABLE _baseline_empty_database_guard (
  ready INTEGER NOT NULL
    CONSTRAINT baseline_requires_empty_database CHECK (ready = 1)
);

INSERT INTO _baseline_empty_database_guard (ready)
VALUES (
  CASE
    WHEN NOT EXISTS (
           SELECT 1 FROM sqlite_schema
            WHERE type = 'table'
              AND name NOT LIKE 'sqlite\_%' ESCAPE '\'
              AND name NOT LIKE '\_cf\_%' ESCAPE '\'
              AND name <> 'd1_migrations'
              AND name <> '_baseline_empty_database_guard'
         )
     AND NOT EXISTS (SELECT 1 FROM d1_migrations)
    THEN 1
    ELSE 0
  END
);

DROP TABLE _baseline_empty_database_guard;

-- Tables.
CREATE TABLE agent_inference_payload_logs (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  request_id TEXT NOT NULL,
  parent_request_id TEXT,
  workstream_id TEXT,
  turn_id TEXT NOT NULL,
  source TEXT NOT NULL CHECK (source IN ('workstream', 'automation_compiler', 'inline_child')),
  provider TEXT NOT NULL,
  model TEXT NOT NULL,
  provider_model TEXT NOT NULL,
  metadata_json TEXT NOT NULL,
  object_key TEXT NOT NULL UNIQUE,
  payload_sha256 TEXT NOT NULL,
  payload_bytes INTEGER NOT NULL CHECK (payload_bytes >= 0),
  outcome TEXT CHECK (outcome IN ('success', 'retry', 'defect', 'fallback', 'failed', 'cancelled')),
  failure_classification TEXT,
  latency_ms INTEGER,
  ttft_ms INTEGER,
  input_tokens INTEGER,
  output_tokens INTEGER,
  context_tokens INTEGER,
  reasoning_tokens INTEGER,
  cached_tokens INTEGER,
  cost_microusd INTEGER,
  response_bytes INTEGER,
  created_at TEXT NOT NULL,
  completed_at TEXT
);

CREATE TABLE audit_events (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  actor_type TEXT NOT NULL CHECK (actor_type IN ('user', 'workspace', 'system', 'connector')),
  actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  workstream_id TEXT REFERENCES workstreams(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  target_type TEXT NOT NULL,
  target_id TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  request_id TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE connector_ingress_routes (
  connection_id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  connector_type TEXT NOT NULL,
  scope TEXT NOT NULL CHECK (scope IN ('personal', 'workspace')),
  provider_account_id TEXT,
  provider_user_id TEXT,
  status TEXT NOT NULL CHECK (status IN ('active', 'disabled')),
  updated_at TEXT NOT NULL
);

CREATE TABLE "desktop_login_tickets" (
  id TEXT PRIMARY KEY,
  ticket_hash TEXT NOT NULL UNIQUE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  expires_at TEXT NOT NULL,
  consumed_at TEXT,
  created_at TEXT NOT NULL,
  desktop_attempt_id TEXT,
  desktop_code_challenge TEXT
);

CREATE TABLE digest_reconciliation_control (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  after_workspace_id TEXT NOT NULL DEFAULT '',
  after_user_id TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL
);

CREATE TABLE github_ingress_pending_deliveries (
  delivery_id TEXT PRIMARY KEY,
  installation_id TEXT NOT NULL CHECK (
    length(installation_id) BETWEEN 1 AND 32
    AND installation_id NOT GLOB '*[^0-9]*'
  ),
  event_type TEXT NOT NULL,
  action TEXT,
  signature_header TEXT NOT NULL,
  payload_ref TEXT NOT NULL,
  received_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  dispatched_at TEXT
);

CREATE TABLE github_installation_routes (
  installation_id TEXT NOT NULL CHECK (
    length(installation_id) BETWEEN 1 AND 32
    AND installation_id NOT GLOB '*[^0-9]*'
  ),
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  workspace_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  disabled_at TEXT,
  PRIMARY KEY (installation_id, region, workspace_id)
);

CREATE TABLE linear_organization_routes (
  organization_id TEXT NOT NULL CHECK (length(organization_id) BETWEEN 1 AND 200),
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  workspace_id TEXT NOT NULL,
  connection_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  disabled_at TEXT,
  PRIMARY KEY (organization_id, region, workspace_id, connection_id)
);

CREATE TABLE notion_webhook_setup_nonces (
  nonce_hash TEXT PRIMARY KEY CHECK (length(nonce_hash) = 43),
  verification_token_hash TEXT CHECK (
    verification_token_hash IS NULL OR length(verification_token_hash) = 43
  ),
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  consumed_at TEXT,
  is_current INTEGER NOT NULL DEFAULT 1 CHECK (is_current IN (0, 1)),
  CHECK (
    (consumed_at IS NULL AND verification_token_hash IS NULL)
    OR (consumed_at IS NOT NULL AND verification_token_hash IS NOT NULL)
  )
);

CREATE TABLE notion_workspace_routes (
  notion_workspace_id TEXT NOT NULL CHECK (length(notion_workspace_id) BETWEEN 1 AND 200),
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  workspace_id TEXT NOT NULL,
  connection_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  disabled_at TEXT,
  PRIMARY KEY (notion_workspace_id, region, workspace_id, connection_id)
);

CREATE TABLE oauth_states (
  id TEXT PRIMARY KEY,
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  provider TEXT NOT NULL,
  purpose TEXT NOT NULL,
  code_verifier_encrypted TEXT NOT NULL,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
  return_uri TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  consumed_at TEXT
, workspace_name TEXT, invitation_id TEXT REFERENCES workspace_invitations(id) ON DELETE SET NULL, desktop_attempt_id TEXT, desktop_code_challenge TEXT);

CREATE TABLE platform_workspace_bindings (
  platform_user_id TEXT PRIMARY KEY,
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  workspace_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'active')),
  operation_id TEXT NOT NULL UNIQUE,
  pending_expires_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, placement_affinity TEXT NOT NULL DEFAULT 'wnam'
  CHECK (placement_affinity IN ('wnam', 'enam', 'weur', 'eeur')));

CREATE TABLE provider_webhook_challenges (
  provider TEXT NOT NULL CHECK (provider IN ('notion')),
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  encrypted_token TEXT NOT NULL,
  token_iv TEXT NOT NULL,
  credential_key_version INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  consumed_at TEXT, setup_nonce_hash TEXT CHECK (
    setup_nonce_hash IS NULL OR length(setup_nonce_hash) = 43
  ), setup_generation INTEGER CHECK (
    setup_generation IS NULL OR setup_generation > 0
  ),
  PRIMARY KEY (provider, region)
);

CREATE TABLE provider_webhook_receipts (
  provider TEXT NOT NULL CHECK (provider IN ('github', 'linear', 'notion')),
  delivery_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  payload_ref TEXT NOT NULL,
  received_at TEXT NOT NULL,
  processed_at TEXT,
  error_json TEXT,
  PRIMARY KEY (provider, delivery_id)
);

CREATE TABLE regional_onboarding_operations (
  operation_id TEXT PRIMARY KEY,
  platform_user_id TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('activate', 'accept', 'create')),
  workspace_id TEXT NOT NULL,
  invitation_id TEXT,
  completed_at TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE TABLE resend_webhook_receipts (
  svix_id TEXT PRIMARY KEY,
  resend_email_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  received_at TEXT NOT NULL,
  routed_at TEXT,
  error_json TEXT
);

CREATE TABLE "sessions" (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  refresh_token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  revoked_at TEXT,
  created_at TEXT NOT NULL
, previous_refresh_token_hash TEXT, refresh_rotated_at TEXT);

CREATE TABLE slack_installation_routes (
  team_id TEXT PRIMARY KEY CHECK (length(team_id) BETWEEN 2 AND 100),
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  workspace_id TEXT NOT NULL,
  connection_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  disabled_at TEXT
);

CREATE TABLE telemetry_accepted_events (
  event_id TEXT PRIMARY KEY,
  payload_hash TEXT NOT NULL,
  envelope_json TEXT NOT NULL,
  route TEXT NOT NULL CHECK (route IN ('global', 'eu')),
  routing_basis TEXT NOT NULL CHECK (
    routing_basis IN ('explicit_binding', 'explicit_selection', 'ip_geolocation', 'geolocation_fallback')
  ),
  analytics_subject_id TEXT NOT NULL,
  workspace_analytics_id TEXT,
  subject_user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  accepted_at TEXT NOT NULL,
  normalized_timestamp TEXT NOT NULL,
  delete_at TEXT NOT NULL,
  delivery_state TEXT NOT NULL CHECK (
    delivery_state IN ('pending', 'delivering', 'delivered', 'retrying', 'suppressed', 'terminal', 'expired')
  ),
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  next_attempt_at TEXT,
  delivered_at TEXT,
  terminal_code TEXT,
  CHECK ((route = 'global') OR (delivery_state NOT IN ('delivering', 'delivered', 'retrying')))
);

CREATE TABLE telemetry_crash_access_audit (
  id TEXT PRIMARY KEY,
  crash_id TEXT NOT NULL,
  operator_id TEXT NOT NULL,
  reason_code TEXT NOT NULL CHECK (reason_code IN ('customer_support', 'incident_response')),
  result_code TEXT NOT NULL CHECK (result_code IN ('found', 'not_found', 'expired', 'storage_error')),
  accessed_at TEXT NOT NULL,
  delete_at TEXT NOT NULL
);

CREATE TABLE telemetry_crash_reports (
  crash_id TEXT PRIMARY KEY,
  upload_id TEXT NOT NULL UNIQUE,
  subject_user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  subject_workspace_id TEXT REFERENCES workspaces(id) ON DELETE SET NULL,
  installation_analytics_id TEXT NOT NULL,
  route TEXT NOT NULL CHECK (route IN ('global', 'eu')),
  object_key TEXT NOT NULL UNIQUE,
  byte_size INTEGER NOT NULL CHECK (byte_size > 0 AND byte_size <= 20971520),
  content_sha256 TEXT NOT NULL,
  release TEXT NOT NULL,
  build_id TEXT NOT NULL,
  platform TEXT NOT NULL CHECK (platform IN ('darwin', 'win32', 'linux')),
  architecture TEXT NOT NULL CHECK (architecture IN ('arm64', 'x64')),
  process_role TEXT NOT NULL CHECK (process_role IN ('main', 'renderer', 'utility', 'gpu', 'unknown')),
  launch_id TEXT NOT NULL,
  channel TEXT NOT NULL CHECK (channel IN ('development', 'alpha', 'beta', 'stable')),
  breadcrumbs_json TEXT,
  breadcrumb_status TEXT NOT NULL DEFAULT 'unavailable'
    CHECK (breadcrumb_status IN ('available', 'stale', 'unavailable')),
  parser_state TEXT NOT NULL DEFAULT 'pending'
    CHECK (parser_state IN ('pending', 'processing', 'symbolicated', 'unsymbolicated', 'malformed', 'failed')),
  structured_report_json TEXT,
  issue_fingerprint TEXT,
  processing_attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (processing_attempt_count >= 0),
  processing_next_attempt_at TEXT,
  processing_started_at TEXT,
  destination_state TEXT NOT NULL DEFAULT 'waiting_for_processing'
    CHECK (destination_state IN ('waiting_for_processing', 'pending', 'delivered', 'retrying', 'terminal', 'internal_only', 'suppressed')),
  destination_attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (destination_attempt_count >= 0),
  destination_next_attempt_at TEXT,
  destination_delivered_at TEXT,
  received_at TEXT NOT NULL,
  delete_at TEXT NOT NULL
);

CREATE TABLE telemetry_delivery_receipts (
  event_id TEXT PRIMARY KEY,
  payload_hash TEXT NOT NULL,
  route TEXT NOT NULL CHECK (route IN ('global', 'eu')),
  result_code TEXT NOT NULL,
  created_at TEXT NOT NULL,
  delete_at TEXT NOT NULL
);

CREATE TABLE telemetry_destination_state (
  destination TEXT PRIMARY KEY CHECK (destination IN (
    'posthog_capture', 'posthog_javascript_exception', 'posthog_profile', 'posthog_crash'
  )),
  consecutive_failures INTEGER NOT NULL DEFAULT 0 CHECK (consecutive_failures >= 0),
  circuit_open_until TEXT,
  updated_at TEXT NOT NULL
);

CREATE TABLE telemetry_eu_crash_contributions (
  occurrence_id TEXT PRIMARY KEY,
  fingerprint TEXT NOT NULL CHECK (length(fingerprint) = 64),
  occurred_at TEXT NOT NULL,
  release TEXT NOT NULL,
  build_id TEXT NOT NULL,
  platform TEXT NOT NULL CHECK (platform IN ('darwin', 'win32', 'linux')),
  architecture TEXT NOT NULL CHECK (architecture IN ('arm64', 'x64')),
  process_role TEXT NOT NULL CHECK (process_role IN ('main', 'renderer', 'utility', 'gpu', 'unknown')),
  channel TEXT NOT NULL CHECK (channel IN ('development', 'alpha', 'beta', 'stable')),
  launch_id TEXT NOT NULL,
  delete_at TEXT NOT NULL
);

CREATE TABLE telemetry_eu_events (
  -- This is an independently expiring semantic contribution, not delivery
  -- metadata. A foreign-key cascade would incorrectly truncate its 13-month
  -- analysis window when the 90-day acceptance row is reaped.
  event_id TEXT PRIMARY KEY,
  event_name TEXT NOT NULL,
  schema_version INTEGER NOT NULL,
  identity_scope TEXT NOT NULL,
  analytics_subject_id TEXT NOT NULL,
  workspace_analytics_id TEXT,
  normalized_timestamp TEXT NOT NULL,
  environment TEXT,
  release TEXT,
  build_id TEXT,
  platform TEXT,
  architecture TEXT,
  channel TEXT,
  launch_id TEXT,
  session_id TEXT,
  operation_id TEXT,
  properties_json TEXT NOT NULL,
  delete_at TEXT NOT NULL
);

CREATE TABLE telemetry_identity_links (
  anonymous_epoch_id TEXT PRIMARY KEY,
  analytics_person_id TEXT NOT NULL,
  route TEXT NOT NULL CHECK (route IN ('global', 'eu')),
  linked_at TEXT NOT NULL,
  delete_at TEXT NOT NULL
);

CREATE TABLE telemetry_ingest_rate_buckets (
  surface TEXT NOT NULL CHECK (surface IN ('crash_upload', 'telemetry_bootstrap')),
  subject_hash TEXT NOT NULL CHECK (length(subject_hash) = 43),
  bucket_start TEXT NOT NULL,
  count INTEGER NOT NULL DEFAULT 0 CHECK (count >= 0),
  delete_at TEXT NOT NULL,
  PRIMARY KEY (surface, subject_hash, bucket_start)
);

CREATE TABLE telemetry_maintenance_state (
  task TEXT PRIMARY KEY CHECK (task IN ('crash_object_retention')),
  cursor TEXT,
  updated_at TEXT NOT NULL
);

CREATE TABLE telemetry_onboarding_journeys (
  journey_id TEXT PRIMARY KEY,
  anonymous_epoch_id TEXT NOT NULL UNIQUE,
  route TEXT NOT NULL CHECK (route IN ('global', 'eu')),
  routing_basis TEXT NOT NULL CHECK (routing_basis IN ('ip_geolocation', 'geolocation_fallback')),
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  closed_at TEXT,
  delete_at TEXT NOT NULL
);

CREATE TABLE telemetry_profile_jobs (
  id TEXT PRIMARY KEY,
  subject_user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
  job_kind TEXT NOT NULL CHECK (job_kind IN ('epoch_transition', 'person_profile', 'group_profile')),
  destination_analytics_id TEXT NOT NULL,
  anonymous_epoch_id TEXT,
  properties_json TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version > 0),
  state TEXT NOT NULL CHECK (state IN ('pending', 'delivering', 'acknowledged', 'terminal', 'suppressed')),
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  next_attempt_at TEXT,
  acknowledged_at TEXT,
  created_at TEXT NOT NULL,
  delete_at TEXT NOT NULL,
  CHECK ((job_kind = 'epoch_transition') = (anonymous_epoch_id IS NOT NULL)),
  CHECK ((job_kind = 'group_profile') = (workspace_id IS NOT NULL))
);

CREATE TABLE telemetry_rejection_buckets (
  bucket_start TEXT NOT NULL,
  violation_code TEXT NOT NULL,
  event_name TEXT NOT NULL DEFAULT 'unregistered',
  count INTEGER NOT NULL DEFAULT 0 CHECK (count >= 0),
  delete_at TEXT NOT NULL,
  PRIMARY KEY (bucket_start, violation_code, event_name)
);

CREATE TABLE telemetry_replay_audit (
  id TEXT PRIMARY KEY,
  event_id TEXT NOT NULL,
  operator_id TEXT NOT NULL,
  reason_code TEXT NOT NULL CHECK (reason_code IN ('destination_recovery', 'incident_response')),
  result_code TEXT NOT NULL CHECK (
    result_code IN ('requeued', 'denied', 'not_found', 'wrong_region', 'expired', 'suppressed', 'invalid_state')
  ),
  original_delete_at TEXT,
  created_at TEXT NOT NULL,
  delete_at TEXT NOT NULL
);

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  google_subject TEXT NOT NULL UNIQUE,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  name TEXT NOT NULL,
  avatar_url TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, platform_user_id TEXT, timezone TEXT NOT NULL DEFAULT 'America/Los_Angeles', analytics_person_id TEXT, product_analytics_enabled INTEGER NOT NULL DEFAULT 1
  CHECK (product_analytics_enabled IN (0, 1)), product_analytics_preference_version INTEGER NOT NULL DEFAULT 1
  CHECK (product_analytics_preference_version > 0), preference_subject_handle TEXT);

CREATE TABLE workspace_invitations (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  email TEXT NOT NULL COLLATE NOCASE,
  invited_by_user_id TEXT NOT NULL REFERENCES users(id),
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  accepted_at TEXT,
  created_at TEXT NOT NULL
, role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('admin', 'member')), accepted_by_user_id TEXT REFERENCES users(id), revoked_at TEXT);

CREATE TABLE workspace_members (
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'member')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'invited', 'suspended')),
  joined_at TEXT, last_seen_at TEXT,
  PRIMARY KEY (workspace_id, user_id)
);

CREATE TABLE workspace_product_authority_routes (
  workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,
  generation INTEGER NOT NULL CHECK (generation > 0),
  state TEXT NOT NULL CHECK (state IN ('pending', 'importing', 'verified', 'active', 'quarantined')),
  stage_index INTEGER NOT NULL DEFAULT 0 CHECK (stage_index >= 0),
  source_cursor INTEGER NOT NULL DEFAULT 0 CHECK (source_cursor >= 0),
  row_counts_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(row_counts_json)),
  last_error_code TEXT,
  updated_at TEXT NOT NULL
);

CREATE TABLE workspaces (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE COLLATE NOCASE,
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  created_by_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, timezone TEXT NOT NULL DEFAULT 'America/Los_Angeles', log_agent_inference INTEGER NOT NULL DEFAULT 0
CHECK (log_agent_inference IN (0, 1)), analytics_workspace_id TEXT, placement_affinity TEXT NOT NULL DEFAULT 'wnam'
  CHECK (placement_affinity IN ('wnam', 'enam', 'weur', 'eeur')));

CREATE TABLE workstream_authority_control (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  phase TEXT NOT NULL CHECK (phase IN (
    'legacy_open',
    'maintenance_draining',
    'maintenance_importing',
    'maintenance_verified',
    'durable_object_open',
    'quarantined'
  )),
  generation INTEGER NOT NULL CHECK (generation >= 0),
  required_serving_contract_version INTEGER NOT NULL DEFAULT 1
    CHECK (required_serving_contract_version > 0),
  serving_contract_version INTEGER NOT NULL DEFAULT 0
    CHECK (serving_contract_version >= 0),
  requested_by TEXT,
  reason TEXT,
  started_at TEXT,
  verified_at TEXT,
  opened_at TEXT,
  updated_at TEXT NOT NULL,
  CHECK (
    (phase = 'legacy_open' AND generation = 0)
    OR generation > 0
  )
);

CREATE TABLE workstream_authority_routes (
  workspace_id TEXT NOT NULL,
  workstream_id TEXT PRIMARY KEY,
  generation INTEGER NOT NULL CHECK (generation > 0),
  object_name TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state IN (
    'pending', 'importing', 'verified', 'active', 'quarantined'
  )),
  stage_index INTEGER NOT NULL DEFAULT 0 CHECK (stage_index >= 0),
  source_cursor INTEGER NOT NULL DEFAULT 0 CHECK (source_cursor >= 0),
  source_fence_sequence INTEGER NOT NULL CHECK (source_fence_sequence >= 0),
  source_hash TEXT,
  target_hash TEXT,
  row_counts_json TEXT CHECK (row_counts_json IS NULL OR json_valid(row_counts_json)),
  imported_at TEXT,
  verified_at TEXT,
  activated_at TEXT,
  last_error_code TEXT,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  FOREIGN KEY (workstream_id) REFERENCES workstreams(id) ON DELETE CASCADE,
  UNIQUE (workspace_id, object_name),
  UNIQUE (workstream_id, generation)
);

CREATE TABLE workstream_create_receipts (
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  creator_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_message_id TEXT NOT NULL,
  workstream_id TEXT NOT NULL,
  generation INTEGER NOT NULL CHECK (generation > 0),
  request_hash TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state IN ('reserved', 'initialized', 'completed', 'failed')),
  message_id TEXT,
  harness_run_id TEXT,
  error_code TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (workspace_id, creator_user_id, client_message_id),
  UNIQUE (workstream_id)
);

CREATE TABLE workstream_email_routes (
  local_part TEXT PRIMARY KEY COLLATE NOCASE,
  region TEXT NOT NULL CHECK (region IN ('global', 'eu')),
  workspace_id TEXT NOT NULL,
  workstream_id TEXT,
  automation_subscription_id TEXT,
  status TEXT NOT NULL DEFAULT 'reserved' CHECK (status IN ('reserved', 'active', 'disabled')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  disabled_at TEXT,
  CHECK (
    (workstream_id IS NOT NULL AND automation_subscription_id IS NULL)
    OR (workstream_id IS NULL AND automation_subscription_id IS NOT NULL)
  ),
  UNIQUE (region, workspace_id, workstream_id),
  UNIQUE (region, workspace_id, automation_subscription_id)
);

CREATE TABLE workstreams (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  do_identity_anchor INTEGER NOT NULL DEFAULT 0
  CHECK (do_identity_anchor IN (0, 1)));

-- Control rows the subsumed migrations seed. A column the chain recomputes on
-- every run is re-derived here rather than frozen, so a baselined database is
-- stamped when it is created rather than when this file was generated.
