CREATE TRIGGER users_platform_identity_immutable
BEFORE UPDATE OF platform_user_id ON users
WHEN OLD.platform_user_id IS NOT NULL
  AND (NEW.platform_user_id IS NULL OR NEW.platform_user_id <> OLD.platform_user_id)
BEGIN
  SELECT RAISE(ABORT, 'platform_user_id_immutable');
END;

CREATE TRIGGER workspace_placement_default
AFTER INSERT ON workspaces
WHEN (NEW.region = 'global' AND NEW.placement_affinity NOT IN ('wnam', 'enam'))
  OR (NEW.region = 'eu' AND NEW.placement_affinity NOT IN ('weur', 'eeur'))
BEGIN
  UPDATE workspaces
  SET placement_affinity = CASE NEW.region WHEN 'eu' THEN 'weur' ELSE 'wnam' END
  WHERE id = NEW.id;
END;

CREATE TRIGGER workspace_placement_immutable
BEFORE UPDATE OF placement_affinity ON workspaces
WHEN ((OLD.region = 'global' AND OLD.placement_affinity IN ('wnam', 'enam'))
   OR (OLD.region = 'eu' AND OLD.placement_affinity IN ('weur', 'eeur')))
  AND NEW.placement_affinity <> OLD.placement_affinity
BEGIN
  SELECT RAISE(ABORT, 'workspace_placement_affinity_immutable');
END;

CREATE TRIGGER workspaces_region_immutable
BEFORE UPDATE OF region ON workspaces
WHEN NEW.region <> OLD.region
BEGIN
  SELECT RAISE(ABORT, 'workspace_region_immutable');
END;

CREATE TRIGGER workstream_authority_open_guard
BEFORE UPDATE OF phase ON workstream_authority_control
WHEN NEW.phase = 'durable_object_open' AND (
  OLD.phase != 'maintenance_verified'
  OR NEW.serving_contract_version < NEW.required_serving_contract_version
  OR EXISTS (
    SELECT 1 FROM workstream_authority_routes
     WHERE generation = NEW.generation AND state != 'active'
  )
  OR EXISTS (
    SELECT 1 FROM workspace_product_authority_routes
     WHERE generation = NEW.generation AND state != 'active'
  )
)
BEGIN
  SELECT RAISE(ABORT, 'workstream_authority_not_ready_to_open');
END;

CREATE TRIGGER workstream_authority_phase_transition_guard
BEFORE UPDATE OF phase ON workstream_authority_control
WHEN NEW.phase != OLD.phase AND NOT (
  (OLD.phase = 'legacy_open' AND NEW.phase = 'maintenance_draining')
  OR (OLD.phase = 'maintenance_draining' AND NEW.phase = 'maintenance_importing')
  OR (OLD.phase = 'maintenance_importing' AND NEW.phase IN ('maintenance_verified', 'quarantined'))
  OR (OLD.phase = 'maintenance_verified' AND NEW.phase IN ('durable_object_open', 'quarantined'))
  OR (OLD.phase = 'durable_object_open' AND NEW.phase = 'quarantined')
  OR (OLD.phase = 'quarantined' AND NEW.phase = 'maintenance_draining' AND NEW.generation > OLD.generation)
)
BEGIN
  SELECT RAISE(ABORT, 'workstream_authority_invalid_phase_transition');
END;

CREATE TRIGGER workstream_authority_verified_guard
BEFORE UPDATE OF phase ON workstream_authority_control
WHEN NEW.phase = 'maintenance_verified' AND (
  OLD.phase != 'maintenance_importing'
  OR EXISTS (
    SELECT 1 FROM workstream_authority_routes
     WHERE generation = NEW.generation AND state != 'verified'
  )
  OR EXISTS (
    SELECT 1 FROM workspace_product_authority_routes
     WHERE generation = NEW.generation AND state != 'verified'
  )
)
BEGIN
  SELECT RAISE(ABORT, 'workstream_authority_routes_not_verified');
END;

CREATE TRIGGER workstream_email_routes_identity_immutable
BEFORE UPDATE OF local_part, region, workspace_id, workstream_id, automation_subscription_id
ON workstream_email_routes
WHEN NEW.local_part IS NOT OLD.local_part
  OR NEW.region IS NOT OLD.region
  OR NEW.workspace_id IS NOT OLD.workspace_id
  OR NEW.workstream_id IS NOT OLD.workstream_id
  OR NEW.automation_subscription_id IS NOT OLD.automation_subscription_id
BEGIN
  SELECT RAISE(ABORT, 'email route identities are immutable');
END;

CREATE TRIGGER workstream_email_routes_no_delete
BEFORE DELETE ON workstream_email_routes
BEGIN
  SELECT RAISE(ABORT, 'email routes are permanent tombstones');
END;

CREATE TRIGGER workstreams_reject_post_cutover_delete
BEFORE DELETE ON workstreams
WHEN (SELECT phase FROM workstream_authority_control WHERE id = 1)
  NOT IN ('legacy_open', 'maintenance_draining', 'maintenance_verified')
BEGIN
  SELECT RAISE(ABORT, 'workspace_do_authoritative');
END;

CREATE TRIGGER workstreams_reject_post_cutover_insert
BEFORE INSERT ON workstreams
WHEN (SELECT phase FROM workstream_authority_control WHERE id = 1)
       NOT IN ('legacy_open', 'maintenance_draining')
  AND NEW.do_identity_anchor != 1
BEGIN
  SELECT RAISE(ABORT, 'workstream_do_authoritative');
END;

CREATE TRIGGER workstreams_reject_post_cutover_update
BEFORE UPDATE ON workstreams
WHEN (SELECT phase FROM workstream_authority_control WHERE id = 1) NOT IN ('legacy_open', 'maintenance_draining', 'maintenance_verified')
BEGIN
  SELECT RAISE(ABORT, 'workstream_do_authoritative');
END;

